// @ts-check
/**
 * Regenerates the icon and emoji indexes the picker searches (COS-458).
 *
 *   pnpm icons:generate
 *
 * Run by hand, never at build or at runtime. Two reasons, both deliberate:
 *
 * - The app's CSP is `connect-src 'self'`, so a browser cannot fetch Google's
 *   metadata even if we wanted it to.
 * - The generated files are committed, which pins the icon set. Otherwise the
 *   grid would quietly gain and lose glyphs whenever Google shipped a release,
 *   and a name stored in `Project.icon` could stop drawing without anything in
 *   this repository having changed.
 *
 * Both sources are pinned below. Bump them on purpose, then re-run this and
 * commit the diff.
 */

import { writeFile } from "node:fs/promises";
import { gzipSync } from "node:zlib";
import { fileURLToPath } from "node:url";
import path from "node:path";

/** The undocumented feed behind fonts.google.com/icons. ~6.8 MB of JSON. */
const ICON_METADATA_URL = "https://fonts.google.com/metadata/icons?incomplete=1&key=material_symbols";

/** Emoji, grouped and in Unicode order, with names. */
const EMOJI_GROUPS_URL = "https://cdn.jsdelivr.net/npm/unicode-emoji-json@0.8.0/data-by-group.json";

/** The same emoji keyed to search keywords. */
const EMOJI_KEYWORDS_URL = "https://cdn.jsdelivr.net/npm/emojilib@4.0.2/dist/emoji-en-US.json";

/**
 * `app/layout.tsx` loads exactly this family. An icon Google lists but this
 * family does not carry would render as a blank tile — the font draws nothing
 * for a name it does not know — so those are dropped rather than shipped.
 */
const FAMILY = "Material Symbols Rounded";

const OUT_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "src", "lib", "icons");

const HEADER = `/**
 * GENERATED by \`pnpm icons:generate\` — do not edit by hand.
 * Source: scripts/generate-icon-index.mjs
 */`;

/** Google's response is a JSON hijacking guard followed by the payload. */
async function fetchGoogleJson(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`${url} answered ${response.status}`);
  }
  return JSON.parse((await response.text()).replace(/^\)\]\}'\n/, ""));
}

async function fetchJson(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`${url} answered ${response.status}`);
  }
  return response.json();
}

/**
 * One line per entry — `key`, `label`, then the search terms, tab-separated —
 * and every line already lowercase. That last part is the point: the line *is*
 * the haystack, so searching costs one `indexOf` per entry and loading costs
 * one `split`. A JSON array of 3,896 records would parse into 3,896 objects
 * for the same information.
 *
 * `label` is what a screen reader is told. For an icon it repeats the name,
 * which gzip flattens to nothing; for an emoji it is the only readable thing
 * there is, since the key is the character itself.
 */
function encode(entries) {
  return entries.map(({ key, label, terms }) => `${key}\t${label}\t${terms.join(" ")}`).join("\n");
}

/** How big the thing we are about to commit actually is, over the wire. */
function report(label, payload) {
  const raw = Buffer.byteLength(payload) / 1024;
  const gz = gzipSync(Buffer.from(payload), { level: 9 }).length / 1024;
  console.log(`${label.padEnd(16)} ${raw.toFixed(0)} KB raw · ${gz.toFixed(0)} KB gzipped`);
}

/** A tab or a newline in a tag would silently shift a column. Neither exists today. */
function clean(term) {
  return term.toLowerCase().replace(/\s+/g, " ").trim();
}

async function icons() {
  const metadata = await fetchGoogleJson(ICON_METADATA_URL);

  // The feed lists one record per icon *per family*, so names repeat. Keep the
  // richest record for each — tag coverage differs between the duplicates.
  const byName = new Map();
  for (const icon of metadata.icons) {
    if ((icon.unsupported_families ?? []).includes(FAMILY)) {
      continue;
    }
    const previous = byName.get(icon.name);
    if (!previous || (icon.tags ?? []).length > (previous.tags ?? []).length) {
      byName.set(icon.name, icon);
    }
  }

  const entries = [...byName.values()]
    // `popularity` is Google's own usage count. It decides what the grid shows
    // first, which is the only ordering that helps when the default view is
    // every icon there is.
    .sort((a, b) => b.popularity - a.popularity || a.name.localeCompare(b.name))
    .map((icon) => {
      // A tag that merely repeats a word already in the name buys nothing —
      // the name is searched too — and there are thousands of them.
      const nameWords = new Set(icon.name.split("_"));
      const terms = [];
      const seen = new Set();

      for (const tag of icon.tags ?? []) {
        const term = clean(tag);
        if (term === "" || seen.has(term)) {
          continue;
        }
        seen.add(term);
        if (!nameWords.has(term)) {
          terms.push(term);
        }
      }

      return { key: icon.name, label: icon.name.replace(/_/g, " "), terms };
    });

  const payload = encode(entries);
  report("icons", payload);
  console.log(`${entries.length} icons (${metadata.icons.length} raw records, deduplicated and filtered to ${FAMILY})`);

  await writeFile(
    path.join(OUT_DIR, "material-symbols.generated.ts"),
    `${HEADER}

/** Ligature names carried by ${FAMILY}, most used first, with their search tags. */
export const ICON_INDEX = ${JSON.stringify(payload)};

export const ICON_COUNT = ${entries.length};
`,
  );
}

async function emojis() {
  const [groups, keywords] = await Promise.all([fetchJson(EMOJI_GROUPS_URL), fetchJson(EMOJI_KEYWORDS_URL)]);

  const entries = [];
  for (const group of groups) {
    // The group name joins the haystack so "food" finds every fruit, and the
    // Unicode order the groups arrive in is what makes browsing feel sorted
    // without the grid having to draw section headings.
    const groupTerms = clean(group.name).split(/[^a-z0-9]+/).filter(Boolean);

    for (const emoji of group.emojis) {
      const label = clean(emoji.name);
      const terms = [];
      // The label has its own column and is searched with the rest of the
      // line, so nothing it already says is repeated here.
      const seen = new Set([label, ...label.split(" ")]);

      for (const term of [...(keywords[emoji.emoji] ?? []), ...groupTerms]) {
        const word = clean(term).replace(/_/g, " ");
        if (word !== "" && !seen.has(word)) {
          seen.add(word);
          terms.push(word);
        }
      }

      entries.push({ key: emoji.emoji, label, terms });
    }
  }

  const payload = encode(entries);
  report("emojis", payload);
  console.log(`${entries.length} emoji in ${groups.length} groups`);

  await writeFile(
    path.join(OUT_DIR, "emoji.generated.ts"),
    `${HEADER}

/** Every emoji, in Unicode order — which is grouped order — with search terms. */
export const EMOJI_INDEX = ${JSON.stringify(payload)};

export const EMOJI_COUNT = ${entries.length};
`,
  );
}

await icons();
await emojis();
